Consider a projective strategy $(\psi, A^{\mathrm{A}},B^{\mathrm{A}},L^{\mathrm{A}},A^{\mathrm{B}},B^{\mathrm{B}},L^{\mathrm{B}})$ which passes the $(m,q,d)$-low individual degree test with probability at least $1-\epsilon$. Let $k \geq md$ be an integer. Let  egin{equation*} 
u = 100000 k^2m^4 \cdot \Big(\epsilon^{1/40000} + (d/q)^{1/40000} + e^{-k/(2560000m^2)}\Big). \end{equation*} Then there exists projective measurements $G^{\mathrm{A}}, G^{\mathrm{B}} \in \polymeas{m}{q}{d}$ with the following properties:  egin{enumerate} \item (Consistency with~$A$): On average over $ oldsymbol{u} \sim \mathbb F_q^{m}$,  egin{align*} A^{\mathrm{A},u}_a \otimes I &\simeq_{
u} I \otimes G^{\mathrm{B}}_{[g(u)=a]},\ I \otimes A^{\mathrm{B},u}_a &\simeq_{
u} G^{\mathrm{A}}_{[g(u)=a]} \otimes I. \end{align*} \item (Self-consistency):  egin{equation*} G^{\mathrm{A}}_g \otimes I \simeq_{
u} I \otimes G^{\mathrm{B}}_g. \end{equation*} \end{enumerate}

For general (i.e.\ not necessarily projective)~$A$  egin{align} &\mathop{ f E/}_{{ oldsymbol{x}}} \sum_a \Vert(A^{{ oldsymbol{x}}}_a \otimes I - I \otimes A^{{ oldsymbol{x}}}_a) \ket{\psi}\Vert^2
onumber\ =~&\mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} (A^{{ oldsymbol{x}}}_a \otimes I - I \otimes A^{{ oldsymbol{x}}}_a)^2 \ket{\psi}
onumber\ =~&2\cdot \Big( \mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} (A^{{ oldsymbol{x}}}_a)^2 \otimes I \ket{\psi} - \mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} A^{{ oldsymbol{x}}}_a \otimes A^{{ oldsymbol{x}}}_a \ket{\psi}\Big)
onumber\ \leq~&2\cdot \Big( \mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} A^{{ oldsymbol{x}}}_a \otimes I \ket{\psi} - \mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} A^{{ oldsymbol{x}}}_a \otimes A^{{ oldsymbol{x}}}_a \ket{\psi}\Big). \end{align} This is at most~$2\cdot \delta$ if  egin{equation*} \mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} A^{{ oldsymbol{x}}}_a \otimes A^{{ oldsymbol{x}}}_a \ket{\psi} \geq \mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} A^{{ oldsymbol{x}}}_a \otimes I \ket{\psi} - \delta. \end{equation*} If~$A$ is projective, then \Cref{eq:here's-where-projectivity-would-help} becomes an equality, and so $A^x_a \otimes I \approx_{2\delta} I \otimes A^x_a$ implies that  egin{equation*} \mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} A^{{ oldsymbol{x}}}_a \otimes I \ket{\psi} - \mathop{ f E/}_{{ oldsymbol{x}}} \sum_a  ra{\psi} A^{{ oldsymbol{x}}}_a \otimes A^{{ oldsymbol{x}}}_a \ket{\psi} =  rac{1}{2} \cdot \left(\mathop{ f E/}_{{ oldsymbol{x}}} \sum_a \Vert(A^{{ oldsymbol{x}}}_a \otimes I - I \otimes A^{{ oldsymbol{x}}}_a) \ket{\psi}\Vert^2ight) \leq \delta.\qedhere \end{equation*}

We will begin by showing that  egin{equation} P^x_{[f(a)=b]} \otimes I \approx_{2\delta + 4\sqrt{\epsilon}} I \otimes A_{[f(a)=b]}^x. \end{equation} To do so, our goal is to bound  egin{align} &\mathop{ f E/}_{{ oldsymbol{x}}} \sum_b \Vert(P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes I - I \otimes A_{[f(a)=b]}^{{ oldsymbol{x}}}) \ket{\psi} \Vert^2
onumber\ =~&\mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} (P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes I - I \otimes A_{[f(a)=b]}^{{ oldsymbol{x}}})^2 \ket{\psi} 
onumber\ =~&\mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} \Big((P^{{ oldsymbol{x}}}_{[f(a)=b]})^2 \otimes I + I \otimes (A^{{ oldsymbol{x}}}_{[f(a)=b]})^2 - 2\cdot P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]}\Big) \ket{\psi}
onumber\ \leq~&\mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} \Big(P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes I + I \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]} - 2\cdot P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]}\Big) \ket{\psi}
onumber\ =~& ra{\psi} P \otimes I \ket{\psi} +  ra{\psi} I \otimes A \ket{\psi} - 2\cdot \mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]} \ket{\psi}. \end{align} By \Cref{prop:completeness-transfer-projective-P}, the first term in \Cref{eq:gonna-handle-third-term} is at most  egin{equation*}  ra{\psi} P \otimes I \ket{\psi} \leq  ra{\psi} A \otimes I \ket{\psi} + 2\sqrt{\epsilon}. \end{equation*} As for the third term in \Cref{eq:gonna-handle-third-term}, we can bound it by  egin{align*} \mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]} \ket{\psi} &= \mathop{ f E/}_{{ oldsymbol{x}}} \sum_{a, a': f(a) = f(a')}  ra{\psi} P^{{ oldsymbol{x}}}_{a} \otimes A^{{ oldsymbol{x}}}_{a'} \ket{\psi}\ &\geq \mathop{ f E/}_{{ oldsymbol{x}}} \sum_{a}  ra{\psi} P^{{ oldsymbol{x}}}_{a} \otimes A^{{ oldsymbol{x}}}_{a} \ket{\psi}\ &\geq \mathop{ f E/}_{{ oldsymbol{x}}} \sum_{a}  ra{\psi} A^{{ oldsymbol{x}}}_{a} \otimes A^{{ oldsymbol{x}}}_{a} \ket{\psi} - \sqrt{\epsilon} 	ag{by \Cref{prop:easy-approx-from-approx-delta}} \ &\geq  ra{\psi} A \otimes I \ket{\psi} - \delta - \sqrt{\epsilon}. \end{align*} Putting everything together,  egin{equation*} \eqref{eq:gonna-handle-third-term} \leq ( ra{\psi} A \otimes I \ket{\psi} + 2\sqrt{\epsilon}) +  ra{\psi} A \otimes I \ket{\psi} - 2 \cdot( ra{\psi} A \otimes I \ket{\psi} - \delta - \sqrt{\epsilon}) = 2\delta + 4\sqrt{\epsilon}. \end{equation*} This proves \Cref{eq;what-we-want-to-prove-but-on-wrong-side}. \Cref{prop:two-notions-of-self-consistency-after-evaluation} implies that  egin{equation*} A^x_{[f(a)=b]} \otimes I \approx_{2\delta} I \otimes A^x_{[f(a)=b]}. \end{equation*} Hence, by \Cref{eq;what-we-want-to-prove-but-on-wrong-side},  egin{equation*} P^x_{[f(a)=b]} \otimes I \approx_{2\delta + 4\sqrt{\epsilon}} I \otimes A_{[f(a)=b]}^x \approx_{2\delta} A^x_{[f(a)=b]} \otimes I. \end{equation*} Thus, by \Cref{prop:triangle-inequality-for-approx_delta},  egin{equation*} P^x_{[f(a)=b]} \otimes I \approx_{8\delta + 8\sqrt{\epsilon}}A^x_{[f(a)=b]} \otimes I. \end{equation*} This concludes the proof.

&\mathop{ f E/}_{{ oldsymbol{x}}} \sum_b \Vert(P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes I - I \otimes A_{[f(a)=b]}^{{ oldsymbol{x}}}) \ket{\psi} \Vert^2
onumber\ =~&\mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} (P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes I - I \otimes A_{[f(a)=b]}^{{ oldsymbol{x}}})^2 \ket{\psi} 
onumber\ =~&\mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} \Big((P^{{ oldsymbol{x}}}_{[f(a)=b]})^2 \otimes I + I \otimes (A^{{ oldsymbol{x}}}_{[f(a)=b]})^2 - 2\cdot P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]}\Big) \ket{\psi}
onumber\ \leq~&\mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} \Big(P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes I + I \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]} - 2\cdot P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]}\Big) \ket{\psi}
onumber\ =~& ra{\psi} P \otimes I \ket{\psi} +  ra{\psi} I \otimes A \ket{\psi} - 2\cdot \mathop{ f E/}_{{ oldsymbol{x}}} \sum_b  ra{\psi} P^{{ oldsymbol{x}}}_{[f(a)=b]} \otimes A^{{ oldsymbol{x}}}_{[f(a)=b]} \ket{\psi}.

By \Cref{prop:triangle-inequality-for-vectors-squared} (the triangle inequality for vectors squared),  egin{align*} &\phantom{=}\sum_a \Vert(A_a - C_a)\otimes I \ket{\psi} \Vert^2\ & = \sum_{a 
eq a^*} \Vert(A_a - B_a)\otimes I \ket{\psi} \Vert^2 + \Vert(A_{a^*} - (I-B + B_{a^*}))\otimes I\ket{\psi}\Vert^2\ & \leq \sum_{a 
eq a^*} \Vert(A_a - B_a)\otimes I \ket{\psi} \Vert^2 + 2 \cdot \Vert(A_{a^*} - B_{a^*})\otimes I\ket{\psi}\Vert^2 + 2 \cdot \Vert(I - B) \otimes I\ket{\psi}\Vert^2\ & \leq 2\sum_{a 
eq a^*} \Vert(A_a - B_a)\otimes I \ket{\psi} \Vert^2 + 2 \cdot \Vert(A_{a^*} - B_{a^*})\otimes I\ket{\psi}\Vert^2 + 2 \cdot \Vert(I - B) \otimes I\ket{\psi}\Vert^2\ & = 2\sum_{a} \Vert(A_a - B_a)\otimes I \ket{\psi} \Vert^2 + 2 \cdot \Vert(I - B)\otimes I \ket{\psi}\Vert^2\ & \leq 2 \delta + 2 \cdot \Vert(I - B)\otimes I \ket{\psi}\Vert^2. 	ag{because $A_a \otimes I \approx_{\delta} B_a \otimes I$} \end{align*} The second term we can bound as follows.  egin{align} \Vert(I - B) \otimes I \ket{\psi}\Vert^2 & =  ra{\psi} (I-B)^2 \otimes I \ket{\psi}
onumber\ & \leq  ra{\psi} (I-B)\otimes I \ket{\psi} 	ag{because~$B$ is a sub-measurement}\ & = 1 -  ra{\psi} B\otimes I \ket{\psi}
onumber\ & = 1 - \sum_a  ra{\psi} B_a \otimes I \ket{\psi}
onumber\ & \leq 1 -\sum_a  ra{\psi} B_a^2 \otimes I \ket{\psi}. \end{align} Now, by \Cref{prop:easy-approx-from-approx-delta} and the fact that $A_a\otimes I \approx_{\delta} B_a\otimes I$,  egin{align*} \sum_a  ra{\psi} B_a^2 \otimes I \ket{\psi} & \approx_{\sqrt{\delta}} \sum_a  ra{\psi} (A_a \cdot B_a)\otimes I \ket{\psi}\ & \approx_{\sqrt{\delta}} \sum_a  ra{\psi} A_a^2\otimes I \ket{\psi}\ & \geq  ra{\psi} A \otimes I \ket{\psi}- \zeta 	ag{by \Cref{prop:cool-prop}}\ & = 1 - \zeta. 	ag{because~$A$ is a measurement} \end{align*} Hence, by \Cref{eq:to-return-later-whatevs},  egin{equation*} \Vert(I - B) \otimes I \ket{\psi}\Vert^2 \leq 1 -\sum_a  ra{\psi} B_a^2 \otimes I \ket{\psi} \leq 2\sqrt{\delta} + \zeta. \end{equation*} This concludes the proof.

\Vert(I - B) \otimes I \ket{\psi}\Vert^2 & =  ra{\psi} (I-B)^2 \otimes I \ket{\psi}
onumber\ & \leq  ra{\psi} (I-B)\otimes I \ket{\psi} 	ag{because~$B$ is a sub-measurement}\ & = 1 -  ra{\psi} B\otimes I \ket{\psi}
onumber\ & = 1 - \sum_a  ra{\psi} B_a \otimes I \ket{\psi}
onumber\ & \leq 1 -\sum_a  ra{\psi} B_a^2 \otimes I \ket{\psi}.

We note that the lemma as stated is trivial when $\zeta > 1/4$. As a result, we will assume that  egin{equation} \zeta \leq 1/4. \end{equation} Let $A = \{A_a\}$ and~$B = \{B_a\}$ be POVM measurements such that  egin{equation*} A_a \otimes I \simeq_{\zeta} I \otimes B_a. \end{equation*} By \Cref{prop:simeq-for-measurements}, this implies that  egin{equation*} \sum_a  ra{\psi}A_a \otimes B_a \ket{\psi} \geq 1 - \zeta. \end{equation*} Applying Cauchy-Schwarz, we have  egin{align*} \sum_a  ra{\psi} A_a \otimes B_a \ket{\psi} &= \sum_a  ra{\psi} (A_a \otimes I) \cdot (I \otimes B_a) \ket{\psi}
onumber\ &\leq \sqrt{\sum_a  ra{\psi} (A_a)^2 \otimes I \ket{\psi}} \cdot \sqrt{\sum_a  ra{\psi} I \otimes (B_a)^2 \ket{\psi}}
onumber\ & \leq \sqrt{\sum_a  ra{\psi} (A_a)^2 \otimes I \ket{\psi}} \cdot 1. \end{align*} Taking the square of both sides,  egin{equation*} \sum_a  ra{\psi} (A_a)^2 \otimes I \ket{\psi} \geq \Big(\sum_a  ra{\psi} A_a \otimes B_a \ket{\psi}\Big)^2 \geq (1-\zeta)^2 \geq 1 - 2\zeta = \sum_a  ra{\psi} A_a \otimes I \ket{\psi} - 2\zeta. 	ag{because~$A$ is a measurement} \end{equation*} Rearranging,  egin{equation} \sum_a  ra{\psi} (A_a - (A_a)^2) \otimes I \ket{\psi} \leq 2\zeta. \end{equation} This is all we need the~$B$ measurement for; henceforth, we will derive consequences of~\Cref{eq:A-looks-projective}. In our next lemma, we convert each~$A_a$ to a projective matrix~$R_a$ by rounding each of $A_a$'s large eigenvalues to~$1$ and small eigenvalues to~$0$.  egin{lemma}[Rounding to projectors] There exists a set of projective matrices $\{R_a\}$ such that  egin{equation*} A_a \otimes I \approx_{2\sqrt{\zeta}} R_a \otimes I. \end{equation*} and  egin{equation*} R:= \sum_a R_a \leq (1+2\sqrt{\zeta}) \cdot I. \end{equation*} \end{lemma}  egin{proof} For each~$a$, we write the eigendecomposition of $A_a$ as follows:  egin{equation*} A_a = \sum_i \lambda_{a, i} \cdot\ket{u_{a, i}}  ra{u_{a, i}}. \end{equation*} Let  egin{equation} 0 < \delta \leq 1/2 \end{equation} be a number to be decided later. Let $\mathsf{trunc}_\delta:[0, 1] ightarrow \{0, 1\}$ be the truncation function defined as  egin{equation*} \mathsf{trunc}_\delta(x) = \left\{ egin{array}{rl} 1 & 	ext{if } x \geq 1- \delta,\ 0 & 	ext{otherwise.} \end{array}ight. \end{equation*} Then for each~$a$ we define the matrix $R_a$  egin{equation*} R_a = \mathsf{trunc}_\delta(A_a) = \sum_i \mathsf{trunc}_\delta(\lambda_{a, i}) \cdot \ket{u_{a, i}}  ra{u_{a, i}}. \end{equation*} To analyze this, we will require the following technical lemma.  egin{lemma} For any $x \in [0, 1]$,  egin{equation*} (x - \mathsf{trunc}_\delta(x))^2 \leq  rac{1}{\delta} \cdot (x - x^2). \end{equation*} \end{lemma}  egin{proof} This is proved by case analysis. First, suppose that $x \geq 1 - \delta$. This implies that $\mathsf{trunc}_\delta(x) = 1$. In addition, because $\delta \leq 1/2$ by \Cref{eq:bound-on-delta}, $ x \geq 1 - \delta \geq 1/2 \geq \delta. $ Thus,  egin{align*} (x - \mathsf{trunc}_\delta(x))^2 & = (1-x)^2\ &\leq (1-x)\ &\leq (1-x) \cdot  rac{x}{\delta} 	ag{because $x \geq \delta$}\ &=  rac{1}{\delta} \cdot (x - x^2). \end{align*} Next, suppose that $x < 1 -\delta$. This implies that $\mathsf{trunc}_\delta(x) = 0$. Thus,  egin{align*} (x - \mathsf{trunc}_\delta(x))^2 & = x^2\ &\leq x\ &\leq x \cdot  rac{(1-x)}{\delta} 	ag{because $x \leq 1- \delta$}\ &=  rac{1}{\delta} \cdot (x - x^2). \end{align*} This concludes the proof. \end{proof} As a result, for each~$a$, \Cref{lem:trunc-inequality} implies that  egin{equation*} (A_a - R_a)^2 = (A_a - \mathsf{trunc}_\delta(A_a))^2 \leq  rac{1}{\delta} \cdot (A_a - (A_a)^2). \end{equation*} Thus,  egin{align*} \sum_a \Vert (A_a - R_a) \otimes I \ket{\psi}\Vert^2 = \sum_a  ra{\psi} (A_a - R_a)^2 \otimes I\ket{\psi} &\leq  rac{1}{\delta} \cdot \sum_a  ra{\psi} (A_a - (A_a)^2) \otimes I \ket{\psi}\ &\leq  rac{1}{\delta} \cdot 2\zeta. 	ag{by \Cref{eq:A-looks-projective}} \end{align*} This implies that $A_a \otimes I \approx_{2\zeta/\delta} R_a \otimes I$. Next, for each $x \in [0, 1]$, it follows from the definition of $\mathsf{trunc}_\delta$ that  egin{equation*} \mathsf{trunc}_\delta(x) \leq \left( rac{1}{1-\delta}ight) \cdot x. \end{equation*} Thus, for each~$a$  egin{equation*} R_a = \mathsf{trunc}_\delta(A_a) \leq \left( rac{1}{1-\delta}ight) \cdot A_a. \end{equation*} Summing over all~$a$,  egin{equation*} R = \sum_a R_a \leq \left( rac{1}{1-\delta}ight) \cdot \sum_a A_a = \left( rac{1}{1-\delta}ight) \cdot A = \left( rac{1}{1-\delta}ight) \cdot I, \end{equation*} because~$A$ is a measurement. We note that  egin{equation*}  rac{1}{1-\delta} =  rac{1}{1-\delta} \cdot  rac{1 + 2\delta}{1 + 2\delta} =  rac{1 + 2\delta}{1 + \delta - 2\delta^2} \leq 1 + 2\delta, \end{equation*} because  egin{equation*} 1 + \delta - 2\delta^2 = 1 + \delta\cdot(1-2\delta)\geq 1 \end{equation*} when $\delta \leq 1/2$, which we assumed in \Cref{eq:bound-on-delta}. Hence,  egin{equation*} R \leq (1+ 2\delta) \cdot I. \end{equation*} The lemma now follows by setting $\delta = \sqrt{\zeta}$. Note that we required that $\delta$ be at most $1/2$, which follows from our assumption that $\zeta \leq 1/4$ from \Cref{eq:assumption-on-zeta}. \end{proof} Write $d$ for the dimension of the~$A$ matrices. If the~$\{R_a\}$ matrices from \Cref{lem:projective-non-measurement} formed a projective sub-measurement, then their total rank would be at most~$d$. Even if this is not true, the next lemma shows that we can still post-process them to reduce their total rank to at most~$d$.  egin{lemma}[Rank reduction] There exists a set of projection matrices $\{Q_a\}$ such that  egin{equation*} A_a \otimes I \approx_{12\sqrt{\zeta}} Q_a \otimes I. \end{equation*} and  egin{equation*} Q:= \sum_a Q_a \leq (1+2\sqrt{\zeta}) \cdot I. \end{equation*} Furthermore, $Q$ has bounded total rank:  egin{equation*} \sum_a \mathrm{rank}(Q_a) \leq d. \end{equation*} \end{lemma}  egin{proof} Let $\{R_a\}$ be the set of projective matrices given by \Cref{lem:projective-non-measurement}. For each $a$, let $r_a$ be the rank of $R_a$. Let $r = \sum_a r_a$. If $r \leq d$, then the lemma is trivially satisfied by taking $Q$ to be~$R$ and applying \Cref{lem:projective-non-measurement}. Henceforth, we will assume that $r > d$. We want to reduce~$r$ so that it is at most~$d$. Fortunately, it is already not too much larger than~$d$:  egin{equation} r = \sum_{a} r_a = \sum_{a} \mathrm{tr}(R_a) = \mathrm{tr}(R) \leq (1 + 2\sqrt{\zeta}) \cdot \mathrm{tr}(I) = (1+2\sqrt{\zeta}) \cdot d. \end{equation} Let $\ket{v_{a, 1}}, \ldots, \ket{v_{a, r_a}}$ be an orthonormal basis for the range of $R_a$, so that  egin{equation*} R_a = \sum_{i=1}^{r_a} \ket{v_{a, i}} ra{v_{a,i}}. \end{equation*} To reduce~$r$, we will throw out those $\ket{v_{a,i}}$'s whose overlap with $\ket{\psi}$ is small. For each $a$ and $1 \leq i \leq r_a$, we denote the overlap of $\ket{v_{a,i}}$ and $\ket{\psi}$ by  egin{equation*} o_{a, i} =  ra{\psi} \cdot (\ket{v_{a,i}} ra {v_{a,i}} \otimes I) \cdot\ket{\psi}. \end{equation*} The total overlap is given by  egin{align} \sum_a \sum_{i=1}^{r_a} o_{a, i} &= \sum_a \sum_{i=1}^{r_a}  ra{\psi} \cdot (\ket{v_{a,i}} ra {v_{a,i}} \otimes I) \cdot\ket{\psi}
onumber\ &= \sum_a  ra{\psi} R_a \otimes I \ket{\psi}
onumber\ &=  ra{\psi} R \otimes I \ket{\psi}
onumber\ &\leq (1+2\sqrt{\zeta}) \cdot  ra{\psi} I \otimes I \ket{\psi}
onumber\ &= 1+2\sqrt{\zeta}. \end{align} Now we define $\mathsf{Large}$ to be the set of large overlaps:  egin{equation*} \mathsf{Large} = \{(a, i) \mid 	ext{$o_{a, i}$ is among the~$d$ largest of the $o_{b, j}$'s}\}, \end{equation*} where we break ties arbitrarily, and we define $\mathsf{Small}$ to be the set containing the remaining $(a, i)$'s. We note that $\mathsf{Large}$ is well-defined and has size~$d$ because $r > d$. Hence, \Cref{eq:bound-on-r} implies that  egin{equation} |\mathsf{Small}| = r - |\mathsf{Large}| = r - d \leq (1 + 2\sqrt{\zeta}) \cdot d - d = 2\sqrt{\zeta} \cdot d \leq 2\sqrt{\zeta} \cdot r. \end{equation} Thus, the small $(a,i)$'s have small total overlap:  egin{align} \sum_{(a, i) \in \mathsf{Small}} o_{a, i} \leq  rac{|\mathsf{Small}|}{r} \sum_{a, i} o_{a,i} &\leq 2\sqrt{\zeta} \cdot \sum_{a, i} o_{a,i} 	ag{by \Cref{eq:size-of-small-is-small}}\ &\leq 2\sqrt{\zeta} \cdot (1+2\sqrt{\zeta}) 	ag{by \Cref{eq:total-overlap}}\ & \leq 4\sqrt{\zeta}, \end{align} where the final step uses the assumption that $\zeta \leq 1/4$ from \Cref{eq:assumption-on-zeta}. For each~$a$ we let $\mathsf{Large}_a$ to be set of $i$'s such that $(a,i)$ is contained in $\mathsf{Large}$, and we define $\mathsf{Small}_a$ similarly. We define the matrix  egin{equation*} Q_a = \sum_{i\in \mathsf{Large}_a} \ket{v_{a, i}} ra{v_{a,i}}. \end{equation*} Then clearly  egin{equation*} \sum_a \mathrm{rank}(Q_a) = \sum_a |\mathsf{Large}_a| = |\mathsf{Large}| \leq d. \end{equation*} We can compute the difference  egin{equation*} R_a - Q_a = \sum_{i=1}^{r_a} \ket{v_{a, i}} ra{v_{a,i}} - \sum_{i \in \mathsf{Large}_a} \ket{v_{a, i}} ra{v_{a,i}} = \sum_{i\in \mathsf{Small}_a} \ket{v_{a, i}} ra{v_{a,i}}. \end{equation*} This is a projective Hermitian matrix, which implies that $Q_a \leq R_a$. As a result,  egin{equation*} Q = \sum_a Q_a \leq \sum_a R_a = R \leq (1+2\sqrt{\zeta}) \cdot I. \end{equation*} In addition,  egin{align*} \sum_a \Vert (R_a - Q_a) \otimes I \ket{\psi} \Vert^2 &= \sum_a  ra{\psi}(R_a - Q_a)^2 \otimes I \ket{\psi}\ &= \sum_a  ra{\psi}(R_a - Q_a)\otimes I \ket{\psi} 	ag{because $R_a - Q_a$ is a projector}\ &= \sum_a \sum_{i \in \mathsf{Small}_a}  ra{\psi} \cdot (\ket{v_{a,i}} ra {v_{a,i}} \otimes I) \cdot\ket{\psi}\ &= \sum_a \sum_{i \in \mathsf{Small}_a} o_{a, i}\ &\leq 4\sqrt{\zeta}. 	ag{by \Cref{eq:small-overlaps}} \end{align*} This means that  egin{equation*} R_a \otimes I \approx_{4\sqrt{\zeta}} Q_a \otimes I. \end{equation*} Since we know that $A_a \otimes I \approx_{2\sqrt{\zeta}} R_a \otimes I$ by \Cref{lem:projective-non-measurement}, \Cref{prop:triangle-inequality-for-approx_delta} implies that  egin{equation*} A_a \otimes I \approx_{12\sqrt{\zeta}} Q_a \otimes I. \end{equation*} This completes the proof. \end{proof} Henceforth, we let $Q = \{Q_a\}$ be the set of projective matrices given by \Cref{lem:projective-low-rank-sum}. We now derive a few properties of~$Q$ that follow as a consequence of \Cref{lem:projective-low-rank-sum}. To begin, we show that~$Q$ is almost as complete as~$A$.  egin{lemma}[Completeness of~$Q$]  egin{equation*}  ra{\psi} Q \otimes I \ket{\psi} \geq 1 - 11 \zeta^{1/4}. \end{equation*} \end{lemma}  egin{proof} To begin, we claim that  egin{align}  ra{\psi} Q \otimes I \ket{\psi} & = \sum_a  ra{\psi} Q_a \otimes I \ket{\psi}
