u_i \ket{u_i} ra{u_i} =  rac{1}{\sqrt{1 + 2\sqrt{\zeta}}} \cdot Q. \end{equation*} We note that  egin{equation*}  rac{1}{\sqrt{1 + 2\sqrt{\zeta}}} \geq  rac{1}{\sqrt{1 + 2\sqrt{\zeta} + \zeta}} =  rac{1}{1 + \sqrt{\zeta}} =  rac{1}{1 + \sqrt{\zeta}} \cdot \Big( rac{1-\sqrt{\zeta}}{1-\sqrt{\zeta}}\Big) =  rac{1-\sqrt{\zeta}}{1 - \zeta} \geq 1 - \sqrt{\zeta}. \end{equation*} Hence, $\sqrt{Q} \geq (1-\sqrt{\zeta}) \cdot Q$. As a result, \Cref{lem:Q-completeness} implies that  egin{equation*}  ra{\psi} \sqrt{Q} \otimes I \ket{\psi} \geq (1-\sqrt{\zeta}) \cdot ra{\psi} Q \otimes I \ket{\psi} \geq (1-\sqrt{\zeta}) \cdot \left(1 - 11 \zeta^{1/4}ight) \geq 1 -\sqrt{\zeta} - 11 \zeta^{1/4}. \end{equation*} This concludes the proof. \end{proof} Finally, we show the following lemma, which quantifies a sense in which~$Q$ is ``almost projective".  egin{lemma}[$Q$ is almost projective]  egin{equation*} \sum_a (Q_a \cdot Q \cdot Q_a - Q_a) \leq 4\sqrt{\zeta} \cdot I. \end{equation*} \end{lemma}  egin{proof} \Cref{lem:projective-low-rank-sum} implies that $Q \leq (1 + 2\sqrt{\zeta}) \cdot I$. As a result,  egin{align*} &\sum_a Q_a \cdot Q \cdot Q_a - \sum_a Q_a\ \leq ~&(1 + 2\sqrt{\zeta}) \cdot \sum_a Q_a \cdot I \cdot Q_a - \sum_a Q_a \ = ~&(1+2\sqrt{\zeta}) \cdot \sum_a Q_a - \sum_a Q_a 	ag{because the $Q_a$'s are projectors}\ = ~&(1+2\sqrt{\zeta}) \cdot Q - Q\ = ~& 2\sqrt{\zeta} \cdot Q\ \leq~& 2\sqrt{\zeta} \cdot (1 + 2\sqrt{\zeta}) \cdot I\ \leq~& 2 \sqrt{\zeta} \cdot 2 \cdot I. 	ag{by \Cref{eq:assumption-on-zeta}} \end{align*} This completes the proof. \end{proof} We now arrive at the most important definition in this proof, which is a natural matrix decomposition for the $Q_a$ matrices.  egin{definition}[Matrix decomposition of~$Q_a$] For each $a$, let $m_a$ be the rank of $Q_a$. Let $\ket{v_{a, 1}}, \ldots, \ket{v_{a, m_a}}$ be an orthonormal basis for the range of $Q_a$, so that  egin{equation*} Q_a = \sum_{i=1}^{m_a} \ket{v_{a, i}} ra{v_{a,i}}. \end{equation*} Let $m = \