ger\ &= U \cdot \Sigma_{m 	imes d} \cdot V^\dagger \cdot V \cdot \Sigma_{d 	imes m} \cdot U^\dagger\ &= U \cdot \Sigma_{m 	imes d} \cdot I_{d 	imes d} \cdot \Sigma_{d 	imes m} \cdot U^\dagger 	ag{because~$V$ is a $d 	imes d$ unitary}\ &= U \cdot (\Sigma_{m 	imes m})^2 \cdot U^\dagger 	ag{because~$m \leq d$}. \end{align*} Second,  egin{align*} X^\dagger \cdot X & = \sum_a X^\dagger \cdot T_a X 	ag{because~$T$ is a measurement}\ &= \sum_a Q_a 	ag{by \Cref{lem:qa-restated}}\ &= Q. \end{align*} In addition, we can rewrite $X^\dagger \cdot X$ as  egin{align*} X^\dagger \cdot X &= (U \cdot \Sigma_{m 	imes d} \cdot V^\dagger)^\dagger \cdot (U \cdot \Sigma_{m 	imes d} \cdot V^\dagger)\ &= V \cdot \Sigma_{d 	imes m} \cdot U^\dagger \cdot U \cdot \Sigma_{m 	imes d} \cdot V^\dagger\ &= V \cdot \Sigma_{d 	imes m} \cdot I_{m 	imes m} \cdot \Sigma_{m 	imes d} \cdot V^\dagger 	ag{because~$U$ is an $m 	imes m$ unitary}\ &= V \cdot (\Sigma_{d 	imes d})^2 \cdot V^\dagger. \end{align*} This completes the proof. \end{proof} The following lemma relates an expression in the $X_a$'s with an expression in the~$Q_a$'s that appeared previously in \Cref{lem:q-almost-projective}.  egin{lemma} For each~$a$,  egin{equation*} X_a^\dagger \cdot (X \cdot X^\dagger - I_{m 	imes m})^2 \cdot X_a = Q_a \cdot Q \cdot Q_a - Q_a. \end{equation*} \end{lemma}  egin{proof} Using~\Cref{lem:X-squared} and~\Cref{lem:qa-restated},  egin{equation*} X_a^\dagger \cdot (X \cdot X^\dagger \cdot X \cdot X^\dagger) \cdot X_a = X_a^\dagger \cdot X \cdot Q \cdot X^\dagger \cdot X_a = Q_a \cdot Q \cdot Q_a. \end{equation*} Similarly, because $Q_a$ is projective,  egin{equation*} X_a^\dagger \cdot (X \cdot X^\dagger) \cdot X_a = (X_a^\dagger \cdot X) \cdot (X^\dagger \cdot X_a) = Q_a \cdot Q_a = Q_a. \end{equation*} Finally,  egin{equation*} X_a^\dagger \cdot (I_{m 	imes m}) \cdot X_a = X_a^\dagger \cdot X_a = Q_a. \end{equation*} Putting these together,  egin{align*} &X_a^\dagger \cdot (X \cdot X^\dagger - I_{m 	imes m})^2 \cdot X_a\ =~& X_a^\dagger \cdot (X \cdot X^\dagger \cdot X \cdot X^\dagger - 2 \cdot X\cdot X^\dagger + I_{m 	imes m}) \cdot X_a\ =~& Q_a \cdot Q \cdot Q_a - 2 \cdot Q_a + Q_a\ =~& Q_a \cdot Q \cdot Q_a - Q_a. \end{align*} This completes the proof. \end{proof} Now we are ready to state the projective sub-measurement~$P$ which should approximate~$A$. Before doing so, we give some intuition for the construction.  egin{remark} Suppose that the $Q_a$'s actually formed a projective measurement. This would imply that the vectors $\ket{v_{a, i}}$, over all $a$ and $1 \leq i \leq m_a$ form an orthonormal set. Then the SVD would actually have already been provided in \Cref{eq:looks-like-singular-value-decomposition}; for each $a$ and $1 \leq i \leq m_a$, the corresponding singular value would be~$1$ and the corresponding left- and right-singular vectors would be $\ket{a, i}$ and $\ket{v_{a, i}}$, respectively. In particular, we would have $\Sigma = I_{m 	imes d}$ and $X = U \cdot I_{m 	imes d}\cdot V^\dagger$. \end{remark} In reality, we don't know that $\Sigma = I_{m 	imes d}$. However, we will construct~$P = \{P_a\}$ as if it were. This motivates the following definition.  egin{definition}[Definition of~$P$] Define the matrix  egin{equation*} \widehat{X} = U \cdot I_{m 	imes d} \cdot V^\dagger. \end{equation*} In addition, for each $a$, define the matrices  egin{equation*} \widehat{X}_a = T_a \cdot \widehat{X}, \quad P_a = \widehat{X}_a^\dagger \cdot \widehat{X}_a. \end{equation*} \end{definition} We now give analogues of \Cref{lem:qa-restated,lem:X-squared} for the~$P$ matrices.  egin{lemma}[$P_a$ restated] For each~$a$,  egin{equation*} P_a = \widehat{X}^\dagger \cdot T_a \cdot \widehat{X} = \widehat{X}_a^\dagger \cdot \widehat{X}. \end{equation*} \end{lemma}  egin{proof} This follows from the definition of $\widehat{X}^\dagger_a$ and the fact that $T$ is a projective measurement:  egin{equation*} P_a = \widehat{X}_a^\dagger \cdot \widehat{X}_a = (\widehat{X}^\dagger \cdot T_a) \cdot (T_a \cdot \widehat{X}) = \widehat{X}^\dagger \cdot T_a \cdot \widehat{X} = \widehat{X}_a^\dagger \cdot \widehat{X}.\qedhere \end{equation*} \end{proof}  egin{lemma}[$\widehat{X}$ squared]  egin{equation*} \widehat{X} \cdot \widehat{X}^\dagger = I_{m 	imes m}. \end{equation*} \end{lemma}  egin{proof} First,  egin{align*} \widehat{X} \cdot \widehat{X}^\dagger &= (U \cdot I_{m 	imes d} \cdot V^\dagger) \cdot (U \cdot I_{m 	imes d} \cdot V^\dagger)^\dagger\ &= U \cdot I_{m 	imes d} \cdot V^\dagger \cdot V \cdot I_{d 	imes m} \cdot U^\dagger\ &= U \cdot I_{m 	imes d} \cdot I_{d 	imes d} \cdot I_{d 	imes m} \cdot U^\dagger 	ag{because~$V$ is a $d 	imes d$ unitary}\ &= U \cdot I_{m 	imes m} \cdot U^\dagger 	ag{because~$m \leq d$}\ &= I_{m 	imes m}, \end{align*} where the last step uses the fact that~$U$ is an $m 	imes m$ unitary. \end{proof} Finally, we show two lemmas on quantities involving both $X$ and~$\widehat{X}$.  egin{lemma}[$X$ times $\widehat{X}$]  egin{equation*} X \cdot \widehat{X}^\dagger = U \cdot \Sigma_{m 	imes m} \cdot U^\dagger, \quad 	ext{and} \quad X^\dagger \cdot \widehat{X} = \sqrt{Q}. \end{equation*} \end{lemma}  egin{proof} First,  egin{align*} X \cdot \widehat{X}^\dagger &= (U \cdot \Sigma_{m 	imes d} \cdot V^\dagger) \cdot (U \cdot I_{m 	imes d} \cdot V^\dagger)^\dagger\ &= U \cdot \Sigma_{m 	imes d} \cdot V^\dagger \cdot V \cdot I_{d 	imes m} \cdot U^\dagger\ &= U \cdot \Sigma_{m 	imes d} \cdot I_{d 	imes d} \cdot I_{d 	imes m} \cdot U^\dagger 	ag{because~$V$ is a $d 	imes d$ unitary}\ &= U \cdot \Sigma_{m 	imes m} \cdot U^\dagger 	ag{because~$m \leq d$}. \end{align*} Second,  egin{align*} X^\dagger \cdot \widehat{X} &= (U \cdot \Sigma_{m 	imes d} \cdot V^\dagger)^\dagger \cdot (U \cdot I_{m 	imes d} \cdot V^\dagger)\ &= V \cdot \Sigma_{d 	imes m} \cdot U^\dagger \cdot U \cdot I_{m 	imes d} \cdot V^\dagger\ &= V \cdot \Sigma_{d 	imes m} \cdot I_{m 	imes m} \cdot I_{m 	imes d} \cdot V^\dagger 	ag{because~$U$ is an $m 	imes m$ unitary}\ &= V \cdot \Sigma_{d 	imes d} \cdot V^\dagger\ &= \sqrt{V \cdot (\Sigma_{d 	imes d})^2 \cdot V^\dagger}\ &= \sqrt{Q}. 	ag{by \Cref{lem:X-squared}} \end{align*} This completes the proof. \end{proof}  egin{lemma}[Squared difference]  egin{equation*} (X - \widehat{X}) \cdot (X - \widehat{X})^\dagger \leq (X \cdot X^\dagger - I_{m 	imes m})^2. \end{equation*} \end{lemma}  egin{proof} By~\Cref{lem:X-squared,lem:X-hat-squared,lem:X-times-X-hat},  egin{align*} (X - \widehat{X}) \cdot (X - \widehat{X})^\dagger & = X \cdot X^\dagger - X\cdot \widehat{X}^\dagger - \widehat{X} \cdot X^\dagger + \widehat{X} \cdot \widehat{X}^\dagger\ & = U \cdot \Sigma_{m 	imes m}^2 \cdot U^\dagger - 2 \cdot U \cdot \Sigma_{m 	imes m} \cdot U^\dagger+ I_{m 	imes m}\ & = U \cdot \left(\Sigma_{m 	imes m}^2 - 2 \cdot \Sigma_{m 	imes m} + I_{m 	imes m} ight) \cdot U^\dagger\ & = U \cdot \left(\Sigma_{m 	imes m} - I_{m 	imes m}ight)^2 \cdot U^\dagger. \end{align*} Because $\Sigma_{m 	imes m}$ and $I_{m 	imes m}$ are commuting,  egin{equation*} (\Sigma_{m 	imes m} - I_{m 	imes m})^2 \leq (\Sigma_{m 	imes m} + I_{m 	imes m})^2 \cdot (\Sigma_{m 	imes m} - I_{m 	imes m})^2 = (\Sigma_{m	imes m}^2 - I_{m 	imes m})^2. \end{equation*} As a result,  egin{align*} U \cdot \left(\Sigma_{m 	imes m} - I_{m 	imes m}ight)^2 \cdot U^\dagger & \leq U \cdot \left(\Sigma_{m 	imes m}^2 - I_{m 	imes m}ight)^2 \cdot U^\dagger\ & = \left(U \cdot \Sigma_{m 	imes m}^2 \cdot U^\dagger - I_{m 	imes m} ight)^2\ &= (X \cdot X^\dagger - I_{m 	imes m})^2. 	ag{by \Cref{lem:X-squared}} \end{align*} This completes the proof. \end{proof} The first property we need of~$P$ is that it is a projective sub-measurement. This is shown in the following lemma.  egin{lemma}[Projectivity of~$P$] $P = \{P_a\}$ forms a projective sub-measurement. \end{lemma}  egin{proof} Let $a, b$ be (possibly distinct) outcomes. Then  egin{align*} P_a \cdot P_b &= (\widehat{X}^\dagger \cdot T_a \cdot \widehat{X}) \cdot (\widehat{X}^\dagger \cdot T_b \cdot \widehat{X}) 	ag{by \Cref{lem:pa-restated}}\ &= (\widehat{X}^\dagger \cdot T_a \cdot I_{m 	imes m} \cdot T_b \cdot \widehat{X}) 	ag{by \Cref{lem:X-hat-squared}}\ &= (\widehat{X}^\dagger \cdot T_a \cdot \widehat{X}) \cdot  oldsymbol{1}[a = b] 	ag{because~$T$ is a projective measurement}\ &= P_a \cdot  oldsymbol{1}[a=b]. 	ag{by \Cref{lem:pa-restated}} \end{align*} This completes the proof. \end{proof} The second property we need of~$P$ is that it is close to~$A$. We will first show that it is close to~$Q$.  egin{lemma}[$P$ is close to~$Q$]  egin{equation*} Q_a \otimes I \approx_{30\zeta^{1/4}} P_a \otimes I. \end{equation*} \end{lemma}  egin{proof} Our goal is to upper-bound the quantity  egin{align} &\sum_a  ra{\psi} (Q_a - P_a)^2 \otimes I \ket{\psi}
onumber\ =~& \sum_a  ra{\psi} (Q_a)^2 \otimes I \ket{\psi} + \sum_a  ra{\psi} (P_a)^2 \otimes I \ket{\psi} - \sum_a  ra{\psi} Q_a P_a \otimes I \ket{\psi} - \sum_a  ra{\psi} P_a Q_a \otimes I \ket{\psi}
onumber\ =~&  ra{\psi} Q \otimes I \ket{\psi} +  ra{\psi} P\otimes I \ket{\psi} - \sum_a  ra{\psi} Q_a P_a \otimes I \ket{\psi} - \sum_a  ra{\psi} P_a Q_a \otimes I \ket{\psi}, \end{align} where the last step uses the projectivity of~$Q$ and~$P$. We bound the four terms in \Cref{eq:P-Q-thing-to-bound} separately. First, by \Cref{lem:projective-low-rank-sum},  egin{equation*}  ra{\psi} Q \otimes I \ket{\psi} \leq (1+2\sqrt{\zeta}) \cdot  ra{\psi} I \otimes I \ket{\psi} \leq 1+2\sqrt{\zeta}. \end{equation*} Second, because~$P$ is a sub-measurement,  egin{equation*}  ra{\psi} P \otimes I\ket{\psi} \leq 1. \end{equation*} The third term and fourth terms are significantly more complicated to bound. As they are complex conjugates of each other, we can write their sum as  egin{equation} \sum_a  ra{\psi} Q_a P_a \otimes I \ket{\psi} + \sum_a  ra{\psi} P_a Q_a \otimes I \ket{\psi} = 2 \cdot \mathfrak{R}\Big(\sum_a  ra{\psi} Q_a P_a \otimes I \ket{\psi}\Big). \end{equation} We now focus on the expression on the right-hand side of \Cref{eq:complex-conjugates}. To begin, we use \Cref{lem:qa-restated} to rewrite it as  egin{equation*} \sum_a  ra{\psi} Q_a P_a \otimes I \ket{\psi} = \sum_a  ra{\psi} ((X_a^\dagger \cdot X) \cdot P_a) \otimes I \ket{\psi}. \end{equation*} The main step will be to show that we can exchange the second $X$ for an $\widehat{X}$, i.e.  egin{equation} \sum_a  ra{\psi} (X_a^\dagger \cdot X \cdot P_a) \otimes I \ket{\psi} \approx_{2\zeta^{1/4}} \sum_a  ra{\psi} (X_a^\dagger \cdot \widehat{X} \cdot P_a) \otimes I \ket{\psi}. \end{equation} To show this, we bound the magnitude of the difference.  egin{multline*} \Big|\sum_a  ra{\psi} ((X_a^\dagger \cdot (X - \widehat{X})) \otimes I) \cdot(P_a \otimes I) \ket{\psi}\Big|\ \leq \sqrt{\sum_a  ra{\psi}(X_a^\dagger \cdot (X - \widehat{X}) \cdot (X - \widehat{X})^\dagger \cdot X_a) \otimes I \ket{\psi}}\cdot \sqrt{\sum_a  ra{\psi} (P_a)^2 \otimes I \ket{\psi}}. \end{multline*} The expression inside the first square root is  egin{align*} & \sum_a  ra{\psi}(X_a^\dagger \cdot (X - \widehat{X}) \cdot (X - \widehat{X})^\dagger \cdot X_a) \otimes I \ket{\psi}\ \leq~& \sum_a  ra{\psi} (X_a^\dagger \cdot (X \cdot X^\dagger - I_{m 	imes m})^2 \cdot X_a) \otimes I \ket{\psi}	ag{by \Cref{lem:squared-difference}}\ =~& \sum_a  ra{\psi} (Q_a \cdot Q \cdot Q_a - Q_a) \otimes I \ket{\psi}	ag{by \Cref{lem:X-expression-to-Q-expression}}\ \leq~& 4\sqrt{\zeta} \cdot  ra{\psi} I \otimes I \ket{\psi} 	ag{by~\Cref{lem:q-almost-projective}}\ =~& 4\sqrt{\zeta}. \end{align*} The expression inside the second square root is at most~$1$ because~$P$ is a sub-measurement. Next, we claim that the \Cref{eq:add-a-hat} is in fact a real-valued expression. To see this,  egin{align*} \eqref{eq:add-a-hat} & = \sum_a  ra{\psi} (X_a^\dagger \cdot \widehat{X} \cdot P_a) \otimes I \ket{\psi}\ &= \sum_a  ra{\psi} (X^\dagger \cdot T_a \cdot \widehat{X} \cdot \widehat{X}^\dagger \cdot T_a \cdot \widehat{X}) \otimes I \ket{\psi} 	ag{by \Cref{lem:xa-t,lem:pa-restated}}\ &= \sum_a  ra{\psi} (X^\dagger \cdot T_a \cdot I_{m 	imes m} \cdot T_a \cdot \widehat{X}) \otimes I \ket{\psi} 	ag{by \Cref{lem:X-hat-squared}}\ &= \sum_a  ra{\psi} (X^\dagger \cdot T_a \cdot \widehat{X}) \otimes I \ket{\psi}\ &=  ra{\psi} (X^\dagger \cdot \widehat{X}) \otimes I \ket{\psi} 	ag{because~$T$ is a measurement}\ &=  ra{\psi} \sqrt{Q} \otimes I \ket{\psi} 	ag{by \Cref{lem:X-times-X-hat}}, \end{align*} which is real-valued because~$Q$ is positive semidefinite. As a result, we have  egin{align*} \mathfrak{R}\Big(\sum_a  ra{\psi} Q_a P_a \otimes I \ket{\psi}\Big) & \geq \mathfrak{R}\Big(\sum_a  ra{\psi} (X_a^\dagger \cdot \widehat{X} \cdot P_a) \otimes I \ket{\psi}\Big) - 2\zeta^{1/4} 	ag{by \Cref{eq:add-a-hat}}\ & =  ra{\psi} \sqrt{Q} \otimes I \ket{\psi}- 2\zeta^{1/4}\ & \geq (1 - 12 \zeta^{1/4}) - 2\zeta^{1/4}. 	ag{by \Cref{lem:sqrt-Q-completeness}} \end{align*} In total, \Cref{eq:complex-conjugates} shows that  egin{equation*} \sum_a  ra{\psi} Q_a P_a \otimes I \ket{\psi} + \sum_a  ra{\psi} P_a Q_a \otimes I \ket{\psi} \geq 2 \cdot(1 - 14\zeta^{1/4}). \end{equation*} Putting everything together, we conclude that  egin{equation*} \eqref{eq:P-Q-thing-to-bound} \leq (1 + 2\sqrt{\zeta}) + 1 - 2\cdot (1-14\zeta^{1/4}) = 2\sqrt{\zeta} + 28 \zeta^{1/4} \leq 30 \zeta^{1/4}. \end{equation*} This completes the proof. \end{proof} Finally, we have that  egin{align*} A_a \otimes I &\approx_{12 \sqrt{\zeta}} Q_a \otimes I 	ag{by \Cref{lem:projective-low-rank-sum}}\ &\approx_{30 \zeta^{1/4}} P_a \otimes I. 	ag{by \Cref{lem:P-Q-approx}} \end{align*} Hence, \Cref{prop:triangle-inequality-for-approx_delta} implies that  egin{equation*} A_a \otimes I \approx_{84 \zeta^{1/4}} P_a \otimes I. \end{equation*} This completes the proof.

Let $\{R_a\}$ be the set of projective matrices given by \Cref{lem:projective-non-measurement}. For each $a$, let $r_a$ be the rank of $R_a$. Let $r = \sum_a r_a$. If $r \leq d$, then the lemma is trivially satisfied by taking $Q$ to be~$R$ and applying \Cref{lem:projective-non-measurement}. Henceforth, we will assume that $r > d$. We want to reduce~$r$ so that it is at most~$d$. Fortunately, it is already not too much larger than~$d$:  egin{equation} r = \sum_{a} r_a = \sum_{a} \mathrm{tr}(R_a) = \mathrm{tr}(R) \leq (1 + 2\sqrt{\zeta}) \cdot \mathrm{tr}(I) = (1+2\sqrt{\zeta}) \cdot d. \end{equation} Let $\ket{v_{a, 1}}, \ldots, \ket{v_{a, r_a}}$ be an orthonormal basis for the range of $R_a$, so that  egin{equation*} R_a = \sum_{i=1}^{r_a} \ket{v_{a, i}} ra{v_{a,i}}. \end{equation*} To reduce~$r$, we will throw out those $\ket{v_{a,i}}$'s whose overlap with $\ket{\psi}$ is small. For each $a$ and $1 \leq i \leq r_a$, we denote the overlap of $\ket{v_{a,i}}$ and $\ket{\psi}$ by  egin{equation*} o_{a, i} =  ra{\psi} \cdot (\ket{v_{a,i}} ra {v_{a,i}} \otimes I) \cdot\ket{\psi}. \end{equation*} The total overlap is given by  egin{align} \sum_a \sum_{i=1}^{r_a} o_{a, i} &= \sum_a \sum_{i=1}^{r_a}  ra{\psi} \cdot (\ket{v_{a,i}} ra {v_{a,i}} \otimes I) \cdot\ket{\psi}
onumber\ &= \sum_a  ra{\psi} R_a \otimes I \ket{\psi}
onumber\ &=  ra{\psi} R \otimes I \ket{\psi}
onumber\ &\leq (1+2\sqrt{\zeta}) \cdot  ra{\psi} I \otimes I \ket{\psi}
onumber\ &= 1+2\sqrt{\zeta}. \end{align} Now we define $\mathsf{Large}$ to be the set of large overlaps:  egin{equation*} \mathsf{Large} = \{(a, i) \mid 	ext{$o_{a, i}$ is among the~$d$ largest of the $o_{b, j}$'s}\}, \end{equation*} where we break ties arbitrarily, and we define $\mathsf{Small}$ to be the set containing the remaining $(a, i)$'s. We note that $\mathsf{Large}$ is well-defined and has size~$d$ because $r > d$. Hence, \Cref{eq:bound-on-r} implies that  egin{equation} |\mathsf{Small}| = r - |\mathsf{Large}| = r - d \leq (1 + 2\sqrt{\zeta}) \cdot d - d = 2\sqrt{\zeta} \cdot d \leq 2\sqrt{\zeta} \cdot r. \end{equation} Thus, the small $(a,i)$'s have small total overlap:  egin{align} \sum_{(a, i) \in \mathsf{Small}} o_{a, i} \leq  rac{|\mathsf{Small}|}{r} \sum_{a, i} o_{a,i} &\leq 2\sqrt{\zeta} \cdot \sum_{a, i} o_{a,i} 	ag{by \Cref{eq:size-of-small-is-small}}\ &\leq 2\sqrt{\zeta} \cdot (1+2\sqrt{\zeta}) 	ag{by \Cref{eq:total-overlap}}\ & \leq 4\sqrt{\zeta}, \end{align} where the final step uses the assumption that $\zeta \leq 1/4$ from \Cref{eq:assumption-on-zeta}. For each~$a$ we let $\mathsf{Large}_a$ to be set of $i$'s such that $(a,i)$ is contained in $\mathsf{Large}$, and we define $\mathsf{Small}_a$ similarly. We define the matrix  egin{equation*} Q_a = \sum_{i\in \mathsf{Large}_a} \ket{v_{a, i}} ra{v_{a,i}}. \end{equation*} Then clearly  egin{equation*} \sum_a \mathrm{rank}(Q_a) = \sum_a |\mathsf{Large}_a| = |\mathsf{Large}| \leq d. \end{equation*} We can compute the difference  egin{equation*} R_a - Q_a = \sum_{i=1}^{r_a} \ket{v_{a, i}} ra{v_{a,i}} - \sum_{i \in \mathsf{Large}_a} \ket{v_{a, i}} ra{v_{a,i}} = \sum_{i\in \mathsf{Small}_a} \ket{v_{a, i}} ra{v_{a,i}}. \end{equation*} This is a projective Hermitian matrix, which implies that $Q_a \leq R_a$. As a result,  egin{equation*} Q = \sum_a Q_a \leq \sum_a R_a = R \leq (1+2\sqrt{\zeta}) \cdot I. \end{equation*} In addition,  egin{align*} \sum_a \Vert (R_a - Q_a) \otimes I \ket{\psi} \Vert^2 &= \sum_a  ra{\psi}(R_a - Q_a)^2 \otimes I \ket{\psi}\ &= \sum_a  ra{\psi}(R_a - Q_a)\otimes I \ket{\psi} 	ag{because $R_a - Q_a$ is a projector}\ &= \sum_a \sum_{i \in \mathsf{Small}_a}  ra{\psi} \cdot (\ket{v_{a,i}} ra {v_{a,i}} \otimes I) \cdot\ket{\psi}\ &= \sum_a \sum_{i \in \mathsf{Small}_a} o_{a, i}\ &\leq 4\sqrt{\zeta}. 	ag{by \Cref{eq:small-overlaps}} \end{align*} This means that  egin{equation*} R_a \otimes I \approx_{4\sqrt{\zeta}} Q_a \otimes I. \end{equation*} Since we know that $A_a \otimes I \approx_{2\sqrt{\zeta}} R_a \otimes I$ by \Cref{lem:projective-non-measurement}, \Cref{prop:triangle-inequality-for-approx_delta} implies that  egin{equation*} A_a \otimes I \approx_{12\sqrt{\zeta}} Q_a \otimes I. \end{equation*} This completes the proof.

\sum_a \sum_{i=1}^{r_a} o_{a, i} &= \sum_a \sum_{i=1}^{r_a}  ra{\psi} \cdot (\ket{v_{a,i}} ra {v_{a,i}} \otimes I) \cdot\ket{\psi}
onumber\ &= \sum_a  ra{\psi} R_a \otimes I \ket{\psi}
onumber\ &=  ra{\psi} R \otimes I \ket{\psi}
onumber\ &\leq (1+2\sqrt{\zeta}) \cdot  ra{\psi} I \otimes I \ket{\psi}
onumber\ &= 1+2\sqrt{\zeta}.

We begin by expanding  egin{align} \mathop{ f E/}_{ oldsymbol{u} \sim \mathbb F_q^m} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} M^{ oldsymbol{u}}_o \otimes H_h \ket{\psi} &= \mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} M^{ oldsymbol{u}}_o \otimes H^{ oldsymbol{v}}_h \ket{\psi}
onumber\ &= \mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} M^{ oldsymbol{u}}_o \otimes (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \cdot T_h \cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \ket{\psi}. \end{align} We claim that  egin{equation} \eqref{eq:expand-that-H} \approx_{\sqrt{2\delta}} \mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \cdot M^{ oldsymbol{u}}_o) \otimes (T_h \cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \ket{\psi}. \end{equation} To show this, we bound the magnitude of the difference.  egin{multline} \Big|\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \otimes I - I \otimes A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \cdot (M^{ oldsymbol{u}}_o \otimes (T_h \cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}))\ket{\psi}\Big|\ \leq \sqrt{\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \otimes I - I \otimes A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \cdot (M^{ oldsymbol{u}}_o \otimes T_h) \cdot (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \otimes I - I \otimes A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \ket{\psi}}\ \cdot \sqrt{\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} M^{ oldsymbol{u}}_o \otimes (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \cdot T_h\cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \ket{\psi}}. \end{multline} The term inside the first square root is  egin{align*} &\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{a \in \mathbb F_q}  ra{\psi} (A^{ oldsymbol{v}}_a \otimes I - I \otimes A^{ oldsymbol{v}}_a) \cdot  igg( \sum_{(o, h) \in S_{ oldsymbol{u}},h( oldsymbol{v}) = a}M^{ oldsymbol{u}}_o \otimes T_h igg) \cdot (A^{ oldsymbol{v}}_a \otimes I - I \otimes A^{ oldsymbol{v}}_a) \ket{\psi}\ \leq~&\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{a \in \mathbb F_q}  ra{\psi} (A^{ oldsymbol{v}}_a \otimes I - I \otimes A^{ oldsymbol{v}}_a)^2 \ket{\psi}, 	ag{because $M^{ oldsymbol{u}}$ and $T_h$ are sub-measurements} \end{align*} which is at most~$2\delta$ by \Cref{prop:simeq-to-approx} and because~$A$ is $\delta$-self-consistent. The term inside the second square root is  egin{equation*} \mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} M^{ oldsymbol{u}}_o \otimes H^{ oldsymbol{v}}_h \ket{\psi}, \end{equation*} which is at most~$1$ because $M^{ oldsymbol{u}}$ and $H^{ oldsymbol{v}}$ are sub-measurements. Next, we claim that  egin{equation} \eqref{eq:move-one} \approx_{\sqrt{2\delta}} \mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \cdot M^{ oldsymbol{u}}_o \cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \otimes T_h \ket{\psi}. \end{equation} To show this, we bound the magnitude of the difference.  egin{align} &\Big|\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} ((A^{ oldsymbol{v}}_{h( oldsymbol{v})} \cdot M^{ oldsymbol{u}}_o) \otimes T_h) \cdot (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \otimes I - I \otimes A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \ket{\psi}\Big|
onumber\ &\leq\sqrt{\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \cdot M^{ oldsymbol{u}}_o \cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \otimes T_h \ket{\psi}}
onumber\ &\quad\cdot \sqrt{\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \otimes I - I \otimes A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \cdot (M^{ oldsymbol{u}}_o \otimes T_h) \cdot (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \otimes I - I \otimes A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \ket{\psi}}. \end{align} The term inside the first square root is  egin{align*} &\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_h  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \cdot  igg(\sum_{o:(o, h) \in S_{ oldsymbol{u}}} M^{ oldsymbol{u}}_o  igg)\cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \otimes T_h \ket{\psi}\ \leq~&\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_h  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})})^2 \otimes T_h \ket{\psi}	ag{because~$M$ is a sub-measurement}\ \leq~&\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_h  ra{\psi} I \otimes T_h \ket{\psi}	ag{because~$A^{ oldsymbol{v}}_{h( oldsymbol{v})} \leq I$}\ =~&1.	ag{because~$T$ is a measurement} \end{align*} As for the term inside the second square root, it is equal to the term inside the first square root in \Cref{eq:move-one-cauchy-schwarz}, which we showed was at most $2\delta$. Having moved both $A$'s to the left-hand side, we want to show that  egin{equation} \eqref{eq:move-another} \approx_{\sqrt{\zeta_{\mathrm{variance}}}} \mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{u}}_{h( oldsymbol{u})} \cdot M^{ oldsymbol{u}}_o \cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \otimes T_h \ket{\psi}. \end{equation} To show this, we bound the magnitude of the difference.  egin{multline} \Big|\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} ((A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})}) \cdot M^{ oldsymbol{u}}_o \cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \otimes T_h \ket{\psi}\Big|\ \leq \sqrt{\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} ((A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})}) \cdot M^{ oldsymbol{u}}_o \cdot (A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})})) \otimes T_h \ket{\psi}}\ \cdot \sqrt{\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} \cdot M^{ oldsymbol{u}}_o \cdot A^{ oldsymbol{v}}_{h( oldsymbol{v})}) \otimes T_h \ket{\psi}}. \end{multline} The term inside the first square root is  egin{align*} &\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_h  ra{\psi} ((A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})}) \cdot  igg( \sum_{o:(o, h) \in S_{ oldsymbol{u}}}M^{ oldsymbol{u}}_o igg) \cdot (A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})})) \otimes T_h \ket{\psi}\ \leq~&\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_h  ra{\psi} (A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})})^2 \otimes T_h \ket{\psi}. 	ag{because~$M^{ oldsymbol{u}}$ is a sub-measurement} \end{align*} But $T \in \polysub{m}{q}{d}$, and so by \Cref{lem:global-variance-of-points} this expression is at most $\zeta_{\mathrm{variance}}$. As for the term inside the second square root, it is equal to the term inside the first square root in \Cref{eq:move-another-cauchy-schwarz}, which we showed was at most~$1$. Finally, we want to show that  egin{equation} \eqref{eq:change-one} \approx_{\sqrt{\zeta_{\mathrm{variance}}}} \mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{u}}_{h( oldsymbol{u})} \cdot M^{ oldsymbol{u}}_o \cdot A^{ oldsymbol{u}}_{h( oldsymbol{u})}) \otimes T_h \ket{\psi}. \end{equation} To show this, we bound the magnitude of the difference.  egin{multline*} \Big| \mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{u}}_{h( oldsymbol{u})} \cdot M^{ oldsymbol{u}}_o \cdot (A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})})) \otimes T_h \ket{\psi}\Big|\ \leq \sqrt{\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} (A^{ oldsymbol{u}}_{h( oldsymbol{u})} \cdot M^{ oldsymbol{u}}_o \cdot A^{ oldsymbol{u}}_{h( oldsymbol{u})}) \otimes T_h \ket{\psi}}\ \cdot \sqrt{\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_{(o, h) \in S_{ oldsymbol{u}}}  ra{\psi} ((A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})}) \cdot M^{ oldsymbol{u}}_o \cdot (A^{ oldsymbol{v}}_{h( oldsymbol{v})} - A^{ oldsymbol{u}}_{h( oldsymbol{u})})) \otimes T_h \ket{\psi}}. \end{multline*} The term inside the first square root is  egin{align*} &\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_h  ra{\psi} (A^{ oldsymbol{u}}_{h( oldsymbol{u})} \cdot  igg(\sum_{o:(o, h) \in S_{ oldsymbol{u}}} M^{ oldsymbol{u}}_o  igg)\cdot A^{ oldsymbol{u}}_{h( oldsymbol{u})}) \otimes T_h \ket{\psi}\ \leq~&\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_h  ra{\psi} (A^{ oldsymbol{u}}_{h( oldsymbol{u})})^2 \otimes T_h \ket{\psi}	ag{because~$M$ is a sub-measurement}\ \leq~&\mathop{ f E/}_{ oldsymbol{u},  oldsymbol{v}} \sum_h  ra{\psi} I \otimes T_h \ket{\psi}	ag{because~$A^{ oldsymbol{u}}_{h( oldsymbol{u})} \leq I$}\ =~&1.	ag{because~$T$ is a measurement} \end{align*} As for the term inside the second square root, it is equal to the term inside the first square root in \Cref{eq:change-one-cauchy-schwarz}, which we showed was at most $\zeta_{\mathrm{variance}}$. This concludes the proof with an error of $2\sqrt{2\delta} + 2\sqrt{\zeta_{\mathrm{variance}}}$. The lemma now follows by observing that $2\delta \leq \zeta_{\mathrm{variance}}$.

